const sectionMap = {
  home: document.getElementById("home"),
  materi: document.getElementById("materi"),
  makalah: document.getElementById("makalah"),
  about: document.getElementById("about"),
  "detail-materi": document.getElementById("detail-materi"),
  "detail-makalah": document.getElementById("detail-makalah"),
};

const menuToggle = document.querySelector(".menu-toggle");
const navMenu = document.querySelector(".nav-menu");
const themeToggle = document.getElementById("theme-toggle");
const themeIcon = document.querySelector(".theme-icon");
const materiList = document.getElementById("materi-list");
const makalahList = document.getElementById("makalah-list");
const materiEmpty = document.getElementById("materi-empty");
const makalahEmpty = document.getElementById("makalah-empty");
const searchMateri = document.getElementById("search-materi");
const searchMakalah = document.getElementById("search-makalah");
const filterMateri = document.getElementById("filter-materi");
const filterMakalah = document.getElementById("filter-makalah");
const recentMateri = document.getElementById("recent-materi");
const recentMakalah = document.getElementById("recent-makalah");
const materiDetail = document.getElementById("materi-detail");
const makalahDetail = document.getElementById("makalah-detail");

const uniqueCourses = [
  ...new Set([
    ...materiData.map((item) => item.mataKuliah),
    ...makalahData.map((item) => item.mataKuliah),
  ]),
];

function populateCourseFilters() {
  const options = uniqueCourses
    .map((course) => `<option value="${course}">${course}</option>`)
    .join("");

  filterMateri.insertAdjacentHTML("beforeend", options);
  filterMakalah.insertAdjacentHTML("beforeend", options);
}

function showSection(name) {
  Object.entries(sectionMap).forEach(([key, section]) => {
    section.classList.toggle("active", key === name);
  });

  document.querySelectorAll(".nav-link").forEach((button) => {
    button.classList.toggle("active", button.dataset.section === name);
  });

  navMenu.classList.remove("open");
  menuToggle.setAttribute("aria-expanded", "false");
}

function applyTheme(theme) {
  const isDark = theme === "dark";
  document.body.setAttribute("data-theme", theme);
  localStorage.setItem("theme", theme);

  if (themeToggle) {
    themeToggle.classList.toggle("dark", isDark);
    themeToggle.setAttribute(
      "aria-label",
      isDark ? "Ganti ke Light Mode" : "Ganti ke Dark Mode",
    );
    themeToggle.title = isDark ? "Ganti ke Light Mode" : "Ganti ke Dark Mode";
  }
}

function renderStats() {
  document.getElementById("stat-materi").textContent = materiData.length;
  document.getElementById("stat-makalah").textContent = makalahData.length;
  document.getElementById("stat-matkul").textContent = uniqueCourses.length;
}

function renderRecentCards() {
  const recentMateriData = [...materiData].slice(0, 3);
  const recentMakalahData = [...makalahData].slice(0, 3);

  recentMateri.innerHTML = recentMateriData
    .map(
      (item) => `
        <article class="note-card">
          <span class="card-label">${item.mataKuliah}</span>
          <h3>${item.judul}</h3>
          <div class="meta-row">
            <span>${item.tanggal}</span>
          </div>
          <p>${item.deskripsi}</p>
          <div class="card-actions">
            <button class="read-btn" data-materi-id="${item.id}">Baca Selengkapnya</button>
          </div>
        </article>
      `,
    )
    .join("");

  recentMakalah.innerHTML = recentMakalahData
    .map(
      (item) => `
        <article class="paper-card">
          <span class="card-label">${item.mataKuliah}</span>
          <h3>${item.judul}</h3>
          <div class="meta-row">
            <span>Penulis: ${item.penulis}</span>
          </div>
          <p>${item.deskripsi}</p>
          <div class="card-actions">
            <button class="detail-link" data-makalah-id="${item.id}">Baca Makalah</button>
          </div>
        </article>
      `,
    )
    .join("");
}

function getFilteredMateri() {
  const query = searchMateri.value.trim().toLowerCase();
  const selected = filterMateri.value;

  return materiData.filter((item) => {
    const matchSearch =
      !query ||
      item.judul.toLowerCase().includes(query) ||
      item.mataKuliah.toLowerCase().includes(query) ||
      item.deskripsi.toLowerCase().includes(query);

    const matchFilter =
      selected === "Semua Mata Kuliah" || item.mataKuliah === selected;

    return matchSearch && matchFilter;
  });
}

function getFilteredMakalah() {
  const query = searchMakalah.value.trim().toLowerCase();
  const selected = filterMakalah.value;

  return makalahData.filter((item) => {
    const matchSearch =
      !query ||
      item.judul.toLowerCase().includes(query) ||
      item.mataKuliah.toLowerCase().includes(query) ||
      item.deskripsi.toLowerCase().includes(query);

    const matchFilter =
      selected === "Semua Mata Kuliah" || item.mataKuliah === selected;

    return matchSearch && matchFilter;
  });
}

function renderMateriList() {
  const items = getFilteredMateri();

  if (!items.length) {
    materiList.innerHTML = "";
    materiEmpty.classList.remove("hidden");
    return;
  }

  materiEmpty.classList.add("hidden");
  materiList.innerHTML = items
    .map(
      (item) => `
        <article class="note-card">
          <span class="card-label">${item.mataKuliah}</span>
          <h3>${item.judul}</h3>
          <div class="meta-row">
            <span>${item.tanggal}</span>
          </div>
          <p>${item.deskripsi}</p>
          <div class="card-actions">
            <button class="read-btn" data-materi-id="${item.id}">Baca Selengkapnya</button>
          </div>
        </article>
      `,
    )
    .join("");
}

function renderMakalahList() {
  const items = getFilteredMakalah();

  if (!items.length) {
    makalahList.innerHTML = "";
    makalahEmpty.classList.remove("hidden");
    return;
  }

  makalahEmpty.classList.add("hidden");
  makalahList.innerHTML = items
    .map(
      (item) => `
        <article class="paper-card">
          <span class="card-label">${item.mataKuliah}</span>
          <h3>${item.judul}</h3>
          <div class="meta-row">
            <span>Penulis: ${item.penulis}</span>
          </div>
          <p>${item.deskripsi}</p>
          <div class="card-actions">
            <button class="detail-link" data-makalah-id="${item.id}">Baca Makalah</button>
          </div>
        </article>
      `,
    )
    .join("");
}

function renderMateriDetail(id) {
  const item = materiData.find((entry) => entry.id === Number(id));

  if (!item) {
    materiDetail.innerHTML = `
      <div class="empty-state">
        <h3>Materi Tidak Ditemukan</h3>
        <p>Maaf, materi yang Anda cari tidak tersedia.</p>
        <button class="primary-btn back-btn" data-target="materi">← Kembali ke Materi</button>
      </div>
    `;
    showSection("detail-materi");
    return;
  }

  const isiHtml = item.isi
    .map(
      (section, index) => `
        <div>
          <h2>${index + 1}. ${section.subjudul}</h2>
          <p>${section.konten}</p>
        </div>
      `,
    )
    .join("");

  materiDetail.innerHTML = `
    <div class="detail-header">
      <p class="eyebrow">${item.mataKuliah}</p>
      <h1>${item.judul}</h1>
      <div class="detail-meta">
        <span>📅 ${item.tanggal}</span>
        <span>🏷️ ${item.mataKuliah}</span>
      </div>
    </div>

    <div class="section-body">
      <div>
        <h2>Ringkasan</h2>
        <p>${item.ringkasan}</p>
      </div>
      ${isiHtml}
    </div>
  `;

  showSection("detail-materi");
}

function renderMakalahDetail(id) {
  const item = makalahData.find((entry) => entry.id === Number(id));

  if (!item) {
    makalahDetail.innerHTML = `
      <div class="empty-state">
        <h3>Makalah Tidak Ditemukan</h3>
        <p>Maaf, makalah yang Anda cari tidak tersedia.</p>
        <button class="primary-btn back-btn" data-target="makalah">← Kembali ke Makalah</button>
      </div>
    `;
    showSection("detail-makalah");
    return;
  }

  const daftarPustaka = item.daftarPustaka
    .map((ref, index) => `<li>${index + 1}. ${ref}</li>`)
    .join("");

  makalahDetail.innerHTML = `
    <div class="detail-header">
      <p class="eyebrow">MAKALAH</p>
      <h1>${item.judul}</h1>
      <div class="detail-meta">
        <span>${item.penulis}</span>
        <span>${item.mataKuliah}</span>
      </div>
    </div>

    <div class="section-body makalah-content">
      ${
        item.isiLengkapHtml ||
        `
        <div><h2>ABSTRAK</h2><p>${item.abstrak}</p></div>
        <div><h2>1. PENDAHULUAN</h2><p>${item.pendahuluan}</p></div>
        <div><h2>2. PEMBAHASAN</h2><p>${item.pembahasan}</p></div>
        <div><h2>3. KESIMPULAN</h2><p>${item.kesimpulan}</p></div>
        <div><h2>DAFTAR PUSTAKA</h2><ol>${daftarPustaka}</ol></div>
      `
      }
    </div>
  `;

  showSection("detail-makalah");
}

document.addEventListener("click", (event) => {
  const target = event.target;

  if (target.matches("[data-section]")) {
    const sectionName = target.dataset.section;
    showSection(sectionName);
    return;
  }

  if (target.matches("[data-materi-id]")) {
    renderMateriDetail(target.dataset.materiId);
    return;
  }

  if (target.matches("[data-makalah-id]")) {
    renderMakalahDetail(target.dataset.makalahId);
    return;
  }

  if (target.matches(".back-btn")) {
    const targetSection = target.dataset.target;
    showSection(targetSection);
    return;
  }
});

searchMateri.addEventListener("input", renderMateriList);
searchMakalah.addEventListener("input", renderMakalahList);
filterMateri.addEventListener("change", renderMateriList);
filterMakalah.addEventListener("change", renderMakalahList);

menuToggle.addEventListener("click", () => {
  const isOpen = navMenu.classList.toggle("open");
  menuToggle.setAttribute("aria-expanded", String(isOpen));
});

if (themeToggle) {
  themeToggle.addEventListener("click", () => {
    const currentTheme =
      document.body.getAttribute("data-theme") === "dark" ? "light" : "dark";
    applyTheme(currentTheme);
  });
}

const savedTheme = localStorage.getItem("theme") || "light";
applyTheme(savedTheme);
populateCourseFilters();
renderStats();
renderRecentCards();
renderMateriList();
renderMakalahList();
showSection("home");
